     "t": "code",
     "lang": "python",
     "code": "# 51: Anagram check\ndef are_anagrams(s1, s2):\n    return sorted(s1.lower().replace(\" \", \"\")) == sorted(s2.lower().replace(\" \", \"\"))\nprint(are_anagrams(\"listen\", \"silent\"))  # True\n\n# 52: First non-repeating character\ndef first_unique_char(s):\n    freq = {}\n    for c in s:\n        freq[c] = freq.get(c, 0) + 1\n    for c in s:\n        if freq[c] == 1:\n            return c\n    return None\nprint(first_unique_char(\"leetcode\"))  # l\n\n# 53: Longest common prefix\ndef longest_common_prefix(strs):\n    if not strs:\n        return \"\"\n    prefix = strs[0]\n    for s in strs[1:]:\n        while not s.startswith(prefix):\n            prefix = prefix[:-1]\n    return prefix\nprint(longest_common_prefix([\"flower\", \"flow\", \"flight\"]))  # fl\n\n# 54: Title case converter\ndef title_case(s):\n    return ' '.join(word[0].upper() + word[1:].lower() for word in s.split() if word)\nprint(title_case(\"hello world from python\"))  # Hello World From Python\n\n# 55: Remove all whitespace\ndef remove_whitespace(s):\n    return ''.join(c for c in s if not c.isspace())\nprint(remove_whitespace(\"  h e l l o  \"))  # hello\n\n# 56: Check balanced parentheses\ndef is_balanced(s):\n    stack = []\n    pairs = {')': '(', ']': '[', '}': '{'}\n    for c in s:\n        if c in '([{':\n            stack.append(c)\n        elif c in ')]}':\n            if not stack or stack[-1] != pairs[c]:\n                return False\n            stack.pop()\n    return len(stack) == 0\nprint(is_balanced(\"({[]})\"))  # True\nprint(is_balanced(\"({[})\"))   # False\n\n# 57: Rotate list\ndef rotate_list(lst, k):\n    if not lst:\n        return lst\n    k = k % len(lst)\n    return lst[-k:] + lst[:-k]\nprint(rotate_list([1, 2, 3, 4, 5], 2))  # [4, 5, 1, 2, 3]\n\n# 58: Chunk list into groups\ndef chunk(lst, size):\n    return [lst[i:i + size] for i in range(0, len(lst), size)]\nprint(chunk([1, 2, 3, 4, 5, 6, 7], 3))  # [[1,2,3], [4,5,6], [7]]\n\n# 59: Interleave two lists\ndef interleave(a, b):\n    result = []\n    for x, y in zip(a, b):\n        result.extend([x, y])\n    result.extend(a[len(b):])\n    result.extend(b[len(a):])\n    return result\nprint(interleave([1, 3, 5], [2, 4, 6]))  # [1, 2, 3, 4, 5, 6]\n\n# 60: Find second largest\ndef second_largest(lst):\n    unique = sorted(set(lst), reverse=True)\n    return unique[1] if len(unique) >= 2 else None\nprint(second_largest([10, 20, 4, 45, 99]))  # 45\n\n# 61: Zip dictionaries\ndef zip_dicts(keys, values):\n    return dict(zip(keys, values))\nprint(zip_dicts([\"a\", \"b\", \"c\"], [1, 2, 3]))\n\n# 62: Invert dictionary\ndef invert_dict(d):\n    return {v: k for k, v in d.items()}\nprint(invert_dict({\"a\": 1, \"b\": 2, \"c\": 3}))\n\n# 63: Merge dictionaries\ndef merge_dicts(*dicts):\n    result = {}\n    for d in dicts:\n        result.update(d)\n    return result\nprint(merge_dicts({\"a\": 1}, {\"b\": 2}, {\"c\": 3}))\n\n# 64: Deep merge dictionaries\ndef deep_merge(d1, d2):\n    result = d1.copy()\n    for key, value in d2.items():\n        if key in result and isinstance(result[key], dict) and isinstance(value, dict):\n            result[key] = deep_merge(result[key], value)\n        else:\n            result[key] = value\n    return result\nprint(deep_merge({\"a\": {\"x\": 1}}, {\"a\": {\"y\": 2}, \"b\": 3}))\n\n# 65: Group by key\ndef group_by(items, key_fn):\n    groups = {}\n    for item in items:\n        key = key_fn(item)\n        groups.setdefault(key, []).append(item)\n    return groups\npeople = [(\"Alice\", 30), (\"Bob\", 25), (\"Charlie\", 30), (\"Dave\", 25)]\nprint(group_by(people, lambda p: p[1]))\n\n# 66: Sliding window maximum\ndef sliding_window_max(arr, k):\n    from collections import deque\n    dq = deque()\n    result = []\n    for i, num in enumerate(arr):\n        while dq and dq[0] < i - k + 1:\n            dq.popleft()\n        while dq and arr[dq[-1]] < num:\n            dq.pop()\n        dq.append(i)\n        if i >= k - 1:\n            result.append(arr[dq[0]])\n    return result\nprint(sliding_window_max([1, 3, -1, -3, 5, 3, 6, 7], 3))\n\n# 67: Two sum\ndef two_sum(nums, target):\n    seen = {}\n    for i, num in enumerate(nums):\n        complement = target - num\n        if complement in seen:\n            return [seen[complement], i]\n        seen[num] = i\n    return []\nprint(two_sum([2, 7, 11, 15], 9))  # [0, 1]\n\n# 68: Kadane's algorithm (max subarray sum)\ndef max_subarray_sum(arr):\n    max_sum = current = arr[0]\n    for num in arr[1:]:\n        current = max(num, current + num)\n        max_sum = max(max_sum, current)\n    return max_sum\nprint(max_subarray_sum([-2, 1, -3, 4, -1, 2, 1, -5, 4]))  # 6\n\n# 69: Dutch national flag (sort 0, 1, 2)\ndef sort_012(arr):\n    low, mid, high = 0, 0, len(arr) - 1\n    arr = arr[:]\n    while mid <= high:\n        if arr[mid] == 0:\n            arr[low], arr[mid] = arr[mid], arr[low]\n            low += 1\n            mid += 1\n        elif arr[mid] == 1:\n            mid += 1\n        else:\n            arr[mid], arr[high] = arr[high], arr[mid]\n            high -= 1\n    return arr\nprint(sort_012([2, 0, 1, 2, 0, 1, 0, 2]))\n\n# 70: Majority element (Boyer-Moore)\ndef majority_element(arr):\n    candidate, count = None, 0\n    for num in arr:\n        if count == 0:\n            candidate = num\n        count += 1 if num == candidate else -1\n    return candidate\nprint(majority_element([3, 2, 3, 3, 1, 3, 3]))  # 3\n\n# 71: Spiral matrix traversal\ndef spiral_order(matrix):\n    result = []\n    while matrix:\n        result.extend(matrix.pop(0))\n        if matrix and matrix[0]:\n            for row in matrix:\n                result.append(row.pop())\n        if matrix:\n            result.extend(matrix.pop()[::-1])\n        if matrix and matrix[0]:\n            for row in reversed(matrix):\n                result.append(row.pop(0))\n    return result\nprint(spiral_order([[1,2,3],[4,5,6],[7,8,9]]))\n\n# 72: Zigzag traversal\ndef zigzag(matrix):\n    result = []\n    for i, row in enumerate(matrix):\n        result.extend(row if i % 2 == 0 else reversed(row))\n    return result\nprint(zigzag([[1,2,3],[4,5,6],[7,8,9]]))  # [1,2,3,6,5,4,7,8,9]\n\n# 73: Run-length encoding\ndef rle_encode(s):\n    if not s:\n        return \"\"\n    encoded = []\n    count = 1\n    for i in range(1, len(s)):\n        if s[i] == s[i-1]:\n            count += 1\n        else:\n            encoded.append((s[i-1], count))\n            count = 1\n    encoded.append((s[-1], count))\n    return encoded\nprint(rle_encode(\"aaabbbccdddddd\"))\n\n# 74: Run-length decoding\ndef rle_decode(encoded):\n    return ''.join(char * count for char, count in encoded)\nprint(rle_decode([('a', 3), ('b', 3), ('c', 2), ('d', 6)]))\n\n# 75: Find missing number (1 to n)\ndef find_missing(arr, n):\n    expected = n * (n + 1) // 2\n    return expected - sum(arr)\nprint(find_missing([1, 2, 4, 5, 6], 6))  # 3",
